css:
.resume{--deep-teal: #1A3C34;    
      --navy-shadow: #0F2A3F;  
      --soft-slate: #F5F7FA;   
      --accent-bronze: #B8864A; 
      --text-primary: #1E2B32;  
      --text-secondary: #3A4952; 
      --divider: #DCE3E8;       
      --white-pure: #FFFFFF;
      --page-width: 210mm;
      --page-height: 297mm;
      --margin-h: 0.7in;
      --margin-v: 0.7in;}
.resume{width: var(--page-width);
      min-height: var(--page-height);
      background: var(--white-pure);
      margin: 0 auto;
      box-shadow: 0 12px 30px rgba(0, 0, 0, 0.12);
      padding: var(--margin-v) var(--margin-h);
      font-family: 'Arial', 'Helvetica Neue', 'Calibri', '思源黑体', 'Source Han Sans SC', sans-serif;
      color: var(--text-primary);
      line-height: 1.5;
      display: flex;
      flex-direction: column;
      position: relative;
      page-break-after: avoid;
      page-break-inside: avoid;}
.resume h1, .resume h2, .resume h3, .section-title, .name{font-family: 'Arial', 'Helvetica Neue', 'Calibri', '思源黑体', 'Source Han Sans SC', sans-serif;
      font-weight: 600;
      letter-spacing: -0.2px;}
.header{margin-bottom: 0.45in;
      display: flex;
      flex-direction: column;}
.name{font-size: 28pt;
      font-weight: 700;
      color: var(--deep-teal);
      letter-spacing: 0.8px;
      line-height: 1.1;
      margin-bottom: 6px;}
.title-tagline{font-size: 11.5pt;
      color: var(--text-secondary);
      font-weight: 400;
      margin-bottom: 12px;
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;}
.title-tagline span{display: inline-flex;
      align-items: center;
      gap: 6px;
      color: #2E4A42;}
.contact-row{display: flex;
      flex-wrap: wrap;
      gap: 20px;
      font-size: 10.5pt;
      color: var(--text-secondary);
      margin-top: 10px;
      align-items: center;}
.contact-item{display: inline-flex;
      align-items: center;
      gap: 5px;
      white-space: nowrap;}
.icon-phone::before{content: "📞";
      font-size: 10pt;
      margin-right: 2px;
      color: #3A5A4E;}
.icon-email::before{content: "✉️";
      font-size: 10pt;
      margin-right: 2px;
      color: #3A5A4E;}
.icon-location::before{content: "📍";
      font-size: 10pt;
      margin-right: 2px;
      color: #3A5A4E;}
.title-divider{height: 2px;
      background: var(--divider);
      margin-top: 10px;
      position: relative;
      width: 100%;}
.title-divider::before{content: '';
      position: absolute;
      left: 0;
      top: -2px;
      width: 0.55in;
      height: 4px;
      background: var(--deep-teal);}
.section-title{font-size: 11.5pt;
      font-weight: 700;
      color: var(--deep-teal);
      text-transform: uppercase;
      letter-spacing: 1.2px;
      margin: 0.35in 0 0.15in 0;
      padding-bottom: 5px;
      border-bottom: 1.5px solid var(--divider);
      position: relative;
      display: flex;
      align-items: center;}
.section-title::after{content: '';
      display: inline-block;
      width: 22px;
      height: 1.5px;
      background: var(--accent-bronze);
      margin-left: 10px;}
.experience-item{margin-bottom: 0.22in;}
.exp-header{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      margin-bottom: 4px;}
.company-name{font-weight: 700;
      font-size: 12pt;
      color: var(--navy-shadow);}
.job-title{font-weight: 600;
      font-size: 11pt;
      color: var(--text-primary);
      margin-left: 8px;
      font-style: normal;}
.date-location{font-size: 10pt;
      color: var(--text-secondary);
      font-weight: 400;
      white-space: nowrap;
      margin-left: auto;}
.bullet-list{list-style: none;
      margin-top: 6px;
      padding-left: 0;}
.bullet-list li{font-size: 10.5pt;
      color: var(--text-primary);
      margin-bottom: 5px;
      display: flex;
      align-items: baseline;
      gap: 8px;
      line-height: 1.45;}
.bullet-list li::before{content: "•";
      color: var(--deep-teal);
      font-weight: 700;
      font-size: 13pt;
      display: inline-block;
      width: 16px;
      flex-shrink: 0;}
.skill-tags{display: flex;
      flex-wrap: wrap;
      gap: 10px 16px;
      margin-top: 8px;}
.skill-category{font-weight: 700;
      font-size: 10.5pt;
      color: var(--navy-shadow);
      margin-right: 6px;}
.skill-list{font-size: 10.5pt;
      color: var(--text-primary);
      display: flex;
      flex-wrap: wrap;
      gap: 6px 12px;
      align-items: center;}
.skill-item{background: transparent;
      padding: 2px 0;
      border-bottom: 1px dotted var(--divider);
      white-space: nowrap;}
.education-row{display: flex;
      justify-content: space-between;
      align-items: baseline;
      font-size: 10.5pt;
      margin-bottom: 6px;}
.edu-degree{font-weight: 700;
      color: var(--navy-shadow);}
.edu-school{font-weight: 600;
      color: var(--text-primary);}
.edu-date{color: var(--text-secondary);
      margin-left: auto;}
.resume hr{border: 0;
      border-top: 1px solid var(--divider);
      margin: 8px 0 12px;}
.resume{position: relative;
      border-left: 5px solid var(--deep-teal);}
.resume p, .resume li, .resume span, .resume div{user-select: text;}.summary{font-size:10.5pt;color:#2E3B3A;margin:6px 0 10px}.skill-cat{width:100%;display:flex;flex-wrap:wrap;align-items:baseline;margin-bottom:6px}.project-item{margin-bottom:0.25in}.project-head{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;font-size:10.5pt;margin-bottom:6px}.project-name{font-weight:700;color:#0F2A3F}.project-role{color:#3A4952}.project-date{margin-left:auto;color:#3A4952}.misc-line{display:flex;gap:30px;font-size:10pt;color:#2E3B3A;border-top:1px solid #DCE3E8;padding-top:12px;margin-top:0.25in}.misc-line strong{color:#1A3C34}.lang,.cert{margin-right:8px}
